 static final String READ="function(requested){\n const selects=Array.from(document.querySelectorAll('select'));\n const normal=s=>String(s||'').replace(/\\s+/g,' ').trim();\n function title(s){let label=s.labels&&s.labels.length?s.labels[0].innerText:'';if(!label&&s.parentElement){let p=s.parentElement.cloneNode(true);p.querySelectorAll('select').forEach(x=>x.remove());p.querySelectorAll('[data-trl-filter-summary]').forEach(x=>x.remove());label=p.innerText;}return normal(label||s.getAttribute('aria-label')||s.name||s.id||'SilverTrack filter').slice(0,100);}\n function reported(s){return /reported.*issue|issue.*type/i.test(title(s)+' '+s.id+' '+s.name)||Array.from(s.options).some(o=>/parking.*breach/i.test(o.text));}\n let index=requested;if(index<0){const matches=selects.map((s,i)=>({s,i})).filter(x=>!x.s.disabled&&reported(x.s));if(matches.length===1)index=matches[0].i;else return {filters:selects.map((s,i)=>({index:i,title:title(s)})).filter(x=>!selects[x.index].disabled)};}\n let s=selects[index];if(!s||s.disabled)return {filters:[]};\n return {index,key:s.id||s.name||'select:'+index,title:title(s),reported:reported(s),multiple:s.multiple,options:Array.from(s.options).map((o,i)=>({index:i,value:o.value,text:o.text,all:/^(?:all(?:\\s+(?:issues?|reported issues?|issue types?))?|any(?:\\s+issue)?|\\(?select(?:\\s+issue)?\\)?)$/i.test(normal(o.text)),selected:o.selected,disabled:o.disabled||(o.parentElement.tagName==='OPTGROUP'&&o.parentElement.disabled)})).filter(o=>!o.disabled)};\n}";
